-- BigQuery export for real_downstream.py and production_vs_human.py (run in the console; save as data/bq_llm_tagged_export.csv)
SELECT t.id, t.channel_id, t.model, t.traits_hash, t.tagged_at, t.tutorial, t.informational, t.storytelling, t.reaction, t.challenge, t.review, t.commentary, t.interview, t.comparison, t.vlog, t.transformation, t.news_update, t.advice_tips, t.unboxing_first_look, t.competition, t.prank, t.q_a_audience_participation, t.documentary_investigation, t.gameplay, t.compilation, t.skit, t.travel_exploration, t.music_performance, t.experiment, t.podcast_long_form_conversation, t.livestream_stream_highlights, t.listicle_ranking, t.behind_the_scenes, t.collaboration_guest_feature, t.explainer_video_essay, t.asmr_ambient, t.taste_test_tasting, t.haul_shopping, t.comedy, t.emotional, t.controversy, t.high_energy, t.relatability, t.wholesome_feel_good, t.suspense_cliffhanger, t.nostalgia, t.inspirational_motivational, t.edgy_shock_value, t.calm_relaxing, t.production, t.narrated, t.visual_dependency, t.animation, t.face_on_camera, t.editing_pace, t.music_sound_design, t.on_screen_text_captions, t.scripted, t.location_variety, t.promotional, t.call_to_action, t.trend_participation, t.series_recurring_format, t.giveaway_generosity, t.curiosity_gap_hook, t.celebrity_notable_guest, t.direct_address, t.community_callbacks, t.seasonal_holiday_tie_in, t.food_cooking, t.technology, t.gaming, t.sports, t.music_subject, t.finance_business, t.beauty_fashion, t.fitness_health, t.true_crime_mystery, t.news_politics, t.education_science, t.lifestyle_personal_life, t.diy_crafts, t.pets_animals, t.cars_vehicles, v.statistics_viewCount AS views, v.statistics_likeCount AS likes, v.statistics_commentCount AS comments, v.duration_seconds, v.age_days_at_pull, v.snippet_publishedAt AS published_at, CAST(c.statistics_subscriberCount AS INT64) AS channel_subscribers, c.snippet_title AS channel_title FROM `dso-585-project-16336.youtube.llm_tagged` t JOIN `dso-585-project-16336.youtube.videos` v ON t.id = v.id JOIN `dso-585-project-16336.youtube.channels` c ON v.snippet_channelId = c.id ORDER BY t.id